import type { CtxFor, SwarmExtension } from "swarm-extension";
import { z } from "zod";

export const config = z.object({
  channelId: z.string().min(1),
  includeFailed: z.boolean().default(true),
  maxOutputChars: z.number().int().min(40).max(2000).default(400),
});

const manifest = {
  name: "notify-on-complete",
  description: "Posts a short summary to a Slack channel when a task completes or fails",
  version: "1.0.0",
  runtime: "api",
  assets: { hooks: "hooks.ts" },
  config,
} as const;

type SdkResult = { success?: boolean; status?: number; data?: unknown };

// SDK calls resolve with { success, status, data } and do not throw on a tool error.
// Throwing here makes the failure visible in the run log and counts toward auto-disable.
async function post(ctx: CtxFor<typeof manifest>, message: string): Promise<void> {
  const result = (await ctx.swarm.slack_post({
    channelId: ctx.config.channelId,
    message,
  })) as SdkResult;
  if (!result?.success) {
    throw new Error(
      `slack_post failed (${result?.status ?? "no status"}): ${JSON.stringify(result?.data ?? null).slice(0, 200)}`,
    );
  }
}

function clip(text: string, max: number): string {
  const single = text.replace(/\s+/g, " ").trim();
  return single.length > max ? `${single.slice(0, max - 1)}…` : single;
}

const extension: SwarmExtension<typeof manifest> = (api) => {
  api.on("post.task.completed", async (event, ctx) => {
    const title = event.task.title ?? clip(event.task.task, 80);
    await post(
      ctx,
      `:white_check_mark: *${title}* completed (task \`${event.task.id.slice(0, 8)}\`)\n${clip(event.output, ctx.config.maxOutputChars)}`,
    );
    await ctx.state.incr("notified:completed");
  });

  api.on("post.task.failed", async (event, ctx) => {
    if (!ctx.config.includeFailed) return;
    const title = event.task.title ?? clip(event.task.task, 80);
    await post(
      ctx,
      `:x: *${title}* failed (task \`${event.task.id.slice(0, 8)}\`)\n${clip(event.failureReason, ctx.config.maxOutputChars)}`,
    );
    await ctx.state.incr("notified:failed");
  });
};

export default extension;

import { block, type SwarmExtension } from "swarm-extension";
import { z } from "zod";

// Config: which origins to police and what a ticket reference looks like.
export const config = z.object({
  pattern: z.string().default("\\b[A-Z]{2,10}-\\d+\\b"),
  origins: z.array(z.string()).default(["rest", "mcp", "slack"]),
});

const manifest = {
  name: "require-ticket-ref",
  description: "Blocks new tasks from selected origins unless the description names a ticket",
  version: "1.0.0",
  runtime: "api",
  assets: { hooks: "hooks.ts" },
  config,
} as const;

const extension: SwarmExtension<typeof manifest> = (api) => {
  api.on("pre.task.create", async (event, ctx) => {
    if (!ctx.config.origins.includes(event.origin)) return;
    if (new RegExp(ctx.config.pattern).test(event.description)) return;
    await ctx.state.incr(`blocked:${event.origin}`);
    return block(
      `Task must reference a ticket (pattern ${ctx.config.pattern}). Add the ticket id to the description and retry.`,
    );
  });
};

export default extension;

import { block, type SwarmExtension } from "swarm-extension";
import { z } from "zod";

export const config = z.object({
  marker: z.string().min(1).default("Verified:"),
});

const manifest = {
  name: "require-verification-note",
  description: "Refuses task completion unless the output contains a verification line",
  version: "1.0.0",
  runtime: "api",
  assets: { hooks: "hooks.ts" },
  config,
} as const;

type StoreProgressArgs = { status?: unknown; output?: unknown };

const extension: SwarmExtension<typeof manifest> = (api) => {
  api.on("pre.tool.call", (event, ctx) => {
    if (event.tool !== "store-progress") return;
    if (!event.args || typeof event.args !== "object") return;
    const { status, output } = event.args as StoreProgressArgs;
    if (status !== "completed") return;
    if (typeof output === "string" && output.includes(ctx.config.marker)) return;
    return block(
      `Completion output must contain a "${ctx.config.marker}" line that says how the result was checked. Add it and call store-progress again.`,
    );
  });
};

export default extension;

import type { SwarmExtension } from "swarm-extension";

const manifest = {
  name: "task-digest",
  description: "Daily digest of tasks completed and failed in the last 24 hours",
  version: "1.0.0",
  runtime: "api",
  assets: { hooks: "hooks.ts" },
} as const;

// Keep a running count between digests; the scheduled script reads task history
// directly, this counter is only a cheap live signal in the extension state.
const extension: SwarmExtension<typeof manifest> = (api) => {
  api.on("post.task.completed", async (_event, ctx) => {
    await ctx.state.incr("completed");
  });
  api.on("post.task.failed", async (_event, ctx) => {
    await ctx.state.incr("failed");
  });
};

export default extension;

